   ),
   p: (props: ComponentProps<"p">) => <p className="my-3 leading-relaxed text-fg-muted" {...props} />,
   ul: (props: ComponentProps<"ul">) => (
     <ul className="my-4 space-y-1.5 pl-1 text-fg-muted" {...props} />
