const { chromium } = require("@playwright/test");

(async () => {
  const browser = await chromium.launch({ channel: "chrome" });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto("http://localhost:3000/projects/trelix", { waitUntil: "networkidle" });

  const metrics = await page.evaluate(() => {
    const li = document.querySelector(".prose-portfolio ul li");
    const style = window.getComputedStyle(li);
    const beforeStyle = window.getComputedStyle(li, "::before");
    const liRect = li.getBoundingClientRect();
    return {
      fontSize: style.fontSize,
      lineHeight: style.lineHeight,
      before: {
        width: beforeStyle.width,
        height: beforeStyle.height,
        marginTop: beforeStyle.marginTop,
        backgroundColor: beforeStyle.backgroundColor,
        borderRadius: beforeStyle.borderRadius,
      },
      firstStrongRect: li.querySelector("strong")?.getBoundingClientRect(),
      liRect: { top: liRect.top, left: liRect.left, height: liRect.height }
    };
  });
  console.log("Metrics:", JSON.stringify(metrics, null, 2));
  await browser.close();
})();
'

