const { chromium } = require("@playwright/test");

async function checkPage(browser, path, width, height) {
  const page = await browser.newPage({ viewport: { width, height } });
  await page.goto(`http://localhost:3000${path}`, { waitUntil: "networkidle" });

  const data = await page.evaluate(() => {
    const lis = Array.from(document.querySelectorAll(".prose-portfolio ul li"));
    return lis.map((li, idx) => {
      const liRect = li.getBoundingClientRect();
      const code = li.querySelector("code");
      const strong = li.querySelector("strong");
      const wrapper = li.firstElementChild;
      return {
        idx,
        textSnippet: li.textContent.replace(/\s+/g, " ").trim().slice(0, 50),
        liHeight: Math.round(liRect.height),
        code: code ? {
          text: code.textContent,
          height: Math.round(code.getBoundingClientRect().height),
          width: Math.round(code.getBoundingClientRect().width),
        } : null,
        wrapperTag: wrapper ? wrapper.tagName : null,
        wrapperClasses: wrapper ? wrapper.className : null,
      };
    });
  });

  await page.close();
  return data;
}

(async () => {
  const browser = await chromium.launch({ channel: "chrome" });

  console.log("=== /projects/trelix @ 1440px ===");
  const trelix1440 = await checkPage(browser, "/projects/trelix", 1440, 900);
